":"string","format":"uuid"},"customer_id":{"type":"string","format":"uuid"},"task_id":{"type":"string","format":"uuid"},"reason":{"type":"string","maxLength":10000},"first_detected_at":{"type":"string","format":"date-time"},"last_seen_at":{"type":"string","format":"date-time"},"resolved_at":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]}},"required":["id","customer_id","task_id","reason","first_detected_at","last_seen_at","resolved_at"],"additionalProperties":false}},"sandy_life_task_contexts":{"type":"array","maxItems":1000,"items":{"type":"object","properties":{"id":{"type":"string","format":"uuid"},"customer_id":{"type":"string","format":"uuid"},"task_id":{"type":"string","format":"uuid"},"space_id":{"type":"string","format":"uuid"},"area_key":{"type":"string","maxLength":10000},"created_at":{"type":"string","format":"date-time"}},"required":["id","customer_id","task_id","space_id","area_key","created_at"],"additionalProperties":false}},"sandy_life_goal_tasks":{"type":"array","maxItems":1000,"items":{"type":"object","properties":{"customer_id":{"type":"string","format":"uuid"},"goal_id":{"type":"string","format":"uuid"},"task_id":{"type":"string","format":"uuid"},"created_at":{"type":"string","format":"date-time"}},"required":["customer_id","goal_id","task_id","created_at"],"additionalProperties":false}},"sandy_social_connections":{"type":"array","maxItems":1000,"items":{"type":"object","properties":{"id":{"type":"string","format":"uuid"},"customer_id":{"type":"string","format":"uuid"},"person_id":{"type":"string","format":"uuid"},"related_person_id":{"anyOf":[{"type":"string","format":"uuid"},{"type":"null"}]},"relationship":{"type":"string","maxLength":10000},"evidence_fact_id":{"anyOf":[{"type":"string","format":"uuid"},{"type":"null"}]},"verification_status":{"type":"string","maxLength":10000},"created_at":{"type":"string","format":"date-time"},"updated_at":{"type":"string","format":"date-time"}},"required":["id","customer_id","person_id","related_person_id","relationship","evidence_fact_id","verification_status","created_at","updated_at"],"additionalProperties":false}}},"required":["sandy_task_pins","sandy_company_aliases","sandy_agenda_attention","sandy_life_task_contexts","sandy_life_goal_tasks","sandy_social_connections"],"additionalProperties":false}},"required":["format_version","tenant_id","manifest","manifest_sha256","schema_sha256","complete_tenant_coverage","external_provider_assets_included","tables"],"additionalProperties":false}},"required":["ok","snapshot_id","snapshot_sha256","file_name","export"],"additionalProperties":false},"requires_real_user_session":true,"requirement_ids":[111],"complete_tenant_coverage":false,"contract_sha256":"204d664cb9e0ac13baf258601c4715d777f155eb59b12c666f974a1f9e30fda3"}$c$::jsonb;BEGIN
 IF EXISTS(SELECT 1 FROM public.sandy_operation_registry WHERE operation='supabase.tenant.exports.download') THEN RAISE EXCEPTION 'Tenant export download contract already exists';END IF;
 INSERT INTO public.sandy_operation_registry(operation,domain,description,permission_scope,is_mutation,input_schema,output_schema,handler,api_exposed,ui_exposed,ai_exposed,verified,implementation_state,source_repository,source_path,dependencies,error_contract) VALUES('supabase.tenant.exports.download','supabase','Actual confirmed portal customer downloads their own bounded six-table export; private data never delivered via owner impersonation or an administrative/customer API key.','customer:read',false,contract->'input_schema',contract->'output_schema','sandy-operation-api',false,false,false,false,'awaiting_deployment','ausstyle/web-staging','supabase/functions/sandy-tenant-lifecycle-api/download.ts','["real_confirmed_portal_customer_session","live_download_verification_before_exposure"]'::jsonb,jsonb_build_object('requires_real_user_session',true,'api_key_delegable',false,'contract_sha256',contract->>'contract_sha256','requirement_ids','[111]'::jsonb,'complete_tenant_coverage',false));
END $contracts$;
COMMIT;
